; sprites.asm — Colony sim, Amstrad CPC Mode 0
; ΠΑΡΑΓΕΤΑΙ ΑΥΤΟΜΑΤΑ από tools/make_sprites.py — μην το επεξεργάζεσαι με το χέρι.
;
; Δεδομένα γραμμικά (γραμμή-γραμμή), ΟΧΙ στη διάταξη της μνήμης οθόνης.
;
; Θόλοι, δακτύλιοι, διάδρομοι, σημεία σύνδεσης και εξωτερικές δομές έχουν ΜΑΣΚΑ,
; σε μορφή «mask, data, mask, data...» ανά γραμμή. ΠΡΟΣΟΧΗ: οι σταθερές _W δίνουν
; bytes ΔΕΔΟΜΕΝΩΝ ανά γραμμή — σε sprite με μάσκα η γραμμή καταλαμβάνει 2x αυτό:
;       ld a,(hl) : inc hl : and (de) : ld b,a
;       ld a,(hl) : inc hl : or b     : ld (de),a : inc de
; Τα εικονίδια και τα επικαλύμματα πληρότητας είναι αδιαφανή (μόνο data).
;
; Φόρτωσε το μπλοκ σε διεύθυνση πολλαπλάσιο του 256 (το flip_mode0 θέλει σελίδα).

DOME_S_D    equ 48        ; οπτική διάμετρος
DOME_S_W    equ 8         ; bytes ΔΕΔΟΜΕΝΩΝ ανά γραμμή (η γραμμή είναι 2x, mask+data)
DOME_S_H    equ 32        ; γραμμές τεταρτημορίου
DOME_S_SZ   equ 512       ; bytes ανά τεταρτημόριο (mask+data)
DOME_M_D    equ 80        ; οπτική διάμετρος
DOME_M_W    equ 12        ; bytes ΔΕΔΟΜΕΝΩΝ ανά γραμμή (η γραμμή είναι 2x, mask+data)
DOME_M_H    equ 48        ; γραμμές τεταρτημορίου
DOME_M_SZ   equ 1152      ; bytes ανά τεταρτημόριο (mask+data)
DOME_L_D    equ 112       ; οπτική διάμετρος
DOME_L_W    equ 16        ; bytes ΔΕΔΟΜΕΝΩΝ ανά γραμμή (η γραμμή είναι 2x, mask+data)
DOME_L_H    equ 64        ; γραμμές τεταρτημορίου
DOME_L_SZ   equ 2048      ; bytes ανά τεταρτημόριο (mask+data)

ICON_S_W    equ 6         ; bytes· room_icons_s + type*ICON_S_SZ
ICON_S_H    equ 12  
ICON_S_SZ   equ 72  
ICON_M_W    equ 8         ; bytes· room_icons_m + type*ICON_M_SZ
ICON_M_H    equ 16  
ICON_M_SZ   equ 128 
ICON_L_W    equ 10        ; bytes· room_icons_l + type*ICON_L_SZ
ICON_L_H    equ 20  
ICON_L_SZ   equ 200 
SLOT_W      equ 2           ; θέση αποίκου στον διάδρομο
SLOT_H      equ 8
SLOT_SIZE   equ 16          ; bytes ανά παραλλαγή
SLOT_FIGS   equ 5           ; παραλλαγές: κενή, colonist, carrier, driller, engineer
SLOT_STRIDE equ 80          ; όλες οι παραλλαγές μιας θέσης
SLOT_BANK   equ 640         ; bytes ανά μέγεθος θόλου
CORR_SLOTS  equ 8
            ; corr_slot_gfx + size*SLOT_BANK + slot*SLOT_STRIDE
            ; + fig*SLOT_SIZE   (fig: 0 κενή, 1 άποικος, 2..4 ρομπότ)

CORR_H_W    equ 4
CORR_H_H    equ 8
CORR_V_W    equ 2
CORR_V_H    equ 16
CORR_D_W    equ 8           ; διαγώνιο tile
CORR_D_H    equ 16
CORR_D_SX   equ 4           ; βήμα τοποθέτησης σε bytes
CORR_D_SY   equ 16
MACH_W      equ 6
MACH_H      equ 22
MACH_SIZE   equ 132          ; machines + type*MACH_SIZE
MACH_TYPES  equ 10           ; oxygen, iron, bioplastic, weapons, processors, robots, food, spares, medical, vitromeat
MACH_SLOTS  equ 8           ; θέσεις ανά μέγεθος στον πίνακα

PLANT_SIZE  equ 132          ; ίδιες διαστάσεις με τα μηχανήματα
PLANT_TYPES equ 12          ; plants + type*PLANT_SIZE

; Εξωτερικές δομές: αυτοτελή κτίσματα στο έδαφος, ΟΧΙ μηχανές θόλου.
; Κάθε παραλλαγή έχει δική της ετικέτα· διαστάσεις στο struct_dims.
STRUCT_KINDS equ 5          ; solar, turbine, collector, extractor, mine
            ;  0 peas       starch
            ;  1 rice       starch
            ;  2 potatoes   starch
            ;  3 wheat      starch
            ;  4 maize      starch
            ;  5 tomatoes   veg
            ;  6 lettuce    veg
            ;  7 onions     veg
            ;  8 radishes   veg
            ;  9 mushrooms  veg
            ; 10 medicinal  medicine
            ; 11 tree       morale

CONN_W      equ 2
CONN_H      equ 8
CONN_DIRS   equ 8           ; n,ne,e,se,s,sw,w,nw


