; --- διαστάσεις εξωτερικών δομών, 4 θέσεις ανά δομή ---
; struct_dims + kind*8 + size*2 -> (w bytes, h)· 0,0 = δεν υπάρχει
struct_dims:
    db   4, 16,  8, 32, 12, 48, 16, 64   ; solar — ηλιακό πάνελ — 4 μεγέθη
    db   4, 16,  8, 32, 12, 48,  0,  0   ; turbine — ανεμογεννήτρια
    db   4, 16,  8, 32, 12, 48,  0,  0   ; collector — συσσωρευτής ενέργειας
    db   4, 16,  8, 32, 12, 48,  0,  0   ; extractor — αντλία νερού
    db  16, 64,  0,  0,  0,  0,  0,  0   ; mine — ορυχείο — ένα μέγεθος

machine_count:
    db 1,4,8
    ; s, m, l

; --- θέσεις μηχανημάτων, 8 ανά μέγεθος (255 = κενή) ---
; machine_slots + size*MACH_SLOTS*2 + slot*2 -> (x bytes, y)
machine_slots:
    db   5, 28   ; s θέση 0
    db 255,255   ; s θέση 1
    db 255,255   ; s θέση 2
    db 255,255   ; s θέση 3
    db 255,255   ; s θέση 4
    db 255,255   ; s θέση 5
    db 255,255   ; s θέση 6
    db 255,255   ; s θέση 7
    db   5, 30   ; m θέση 0
    db  12, 30   ; m θέση 1
    db   5, 54   ; m θέση 2
    db  12, 54   ; m θέση 3
    db 255,255   ; m θέση 4
    db 255,255   ; m θέση 5
    db 255,255   ; m θέση 6
    db 255,255   ; m θέση 7
    db  13, 15   ; l θέση 0
    db   6, 26   ; l θέση 1
    db   3, 53   ; l θέση 2
    db   6, 80   ; l θέση 3
    db  12, 91   ; l θέση 4
    db  19, 80   ; l θέση 5
    db  22, 53   ; l θέση 6
    db  19, 26   ; l θέση 7

machine_rules:
    db 1,7,7,7,7,7,7,7,7,7
    ; oxygen, iron, bioplastic, weapons, processors, robots, food, spares, medical, vitromeat

; --- θέσεις εικονιδίου/πληρότητας από το ΚΕΝΤΡΟ του θόλου ---
; interior_ofs + size*2 -> (icon dx bytes, icon dy) από το κέντρο
interior_ofs:
    db 253,238   ; s
    db 252,220   ; m
    db 251,246   ; l

; --- 16 firmware colour numbers, pen 0..15 ---
palette_fw:
    db #00,#01,#0B,#17,#0D,#1A,#18,#0F,#06,#12,#0A,#05,#19,#03,#13,#10
    ; pen  0  FW  0  Black         φόντο / έδαφος
    ; pen  1  FW  1  Blue          σκιές
    ; pen  2  FW 11  Sky blue      δάπεδο θόλου
    ; pen  3  FW 23  Pastel cyan   περίγραμμα θόλου
    ; pen  4  FW 13  White         δάπεδο διαδρόμου
    ; pen  5  FW 26  Bright white  περίγραμμα διαδρόμου
    ; pen  6  FW 24  Bright yellow άποικοι
    ; pen  7  FW 15  Orange        εικονίδια
    ; pen  8  FW  6  Bright red    συναγερμός / εικονίδια
    ; pen  9  FW 18  Bright green  εικονίδια (θερμοκήπιο)
    ; pen 10  FW 10  Cyan          εικονίδια
    ; pen 11  FW  5  Mauve         εικονίδια
    ; pen 12  FW 25  Pastel yellow εικονίδια
    ; pen 13  FW  3  Red           εικονίδια
    ; pen 14  FW 19  Sea green     εικονίδια
    ; pen 15  FW 16  Pink          εικονίδια

; --- 57 bytes γέμισμα για τη σελίδα του flip_mode0 ---
sprites_pad:
    defs 57,#00

